package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Entities_unescape_TriageGen2Test {

    private Entities entities;
    private StringWriter writer;

    @Before
    public void setUp() {
        entities = new Entities();
        writer = new StringWriter();
    }























    @Test
    public void testUnescape_MixedContent() throws IOException {
        entities.addEntity("quot", 34);
        entities.unescape(writer, "text &quot; &amp; &#38; &#x26;");
        // Note: &amp; is a named entity, &#38; is decimal, &#x26; is hex
        // Based on logic: &amp; -> & (if added), &#38; -> &, &#x26; -> &
        // However, the logic for &amp; depends on whether 'amp' is in the entity map.
        // Let's test specifically what we know.
        writer = new StringWriter();
        entities.unescape(writer, "a &lt; b &amp; c &#38; d");
        // If 'amp' is not added via addEntity, it returns &amp;
        assertEquals("a < b &amp; c & d", writer.toString());
    }






}

