import static org.junit.Assert.assertEquals;

public class Entities_unescape_TriageGen2Test {

    private Entities entities;
    private StringWriter writer;

    @Before
    public void setUp() {
        entities = new Entities();
        writer = new StringWriter();
    }



























    @Test
    public void testUnescape_NoContentAfterHash() throws IOException {
        entities.unescape(writer, "&#");
        // This hits the loop but doesn't find a semicolon
        // The current code requires a semicolon to trigger unescape logic
        // If string is " &# ", firstAmp is 1, loop starts. 
        // If no semicolon found, it writes '&'.
        // This test ensures we cover the path where entityContentLen is 0 or 1.
        writer = new StringWriter();
        entities.unescape(writer, "&;");
        assertEquals("", writer.toString()); // entityContent is empty, entityValue stays -1
    }


}

package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Entities_unescape_TriageGen2Test {

    private Entities entities;
    private StringWriter writer;

    @Before
    public void setUp() {
        entities = new Entities();
        writer = new StringWriter();
    }





























    @Test
    public void testUnescape_ComplexSequence() throws IOException {
        entities.addEntity("nbsp", 160);
        entities.unescape(writer, "Start &nbsp; & unknown & #123 ;");
        // &nbsp; -> char 160
        // & unknown ; -> entityValue(" unknown ") -> -1 -> writes & unknown ;
        // & #123 ; -> entityValue (decimal 123)
        // Note: the code handles space in substring. " #123 " -> entityContent.charAt(0) is ' '
        // So it goes to entityName(" #123 ")
        // Let's refine:
        writer = new StringWriter();
        entities.unescape(writer, "&#123;");
        assertEquals("{", writer.toString());
    }
}
